/* ---------- hand-written parts (appended by gen-previews.js) ---------- */

const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

const miniScape = '<svg viewBox="0 0 300 150" preserveAspectRatio="xMidYMid slice" style="position:absolute;inset:0;width:100%;height:100%" aria-hidden="true" focusable="false"><rect width="300" height="55" fill="#fef6e4"/><rect y="55" width="300" height="95" fill="#5fb3c4"/><path d="M0 70 L70 74 C95 95 110 118 140 120 L210 122 C228 115 236 90 250 84 C268 88 280 120 300 140 L300 150 L0 150Z" fill="#ecd7a4"/><ellipse cx="30" cy="42" rx="26" ry="18" fill="#3f7a3a" class="bob"/><ellipse cx="62" cy="46" rx="20" ry="14" fill="#5a9a48" class="bob" style="animation-delay:-2s"/><g stroke="#3f8f4f" stroke-width="2" fill="none"><path class="sway" d="M120 120 q3 -14 -1 -26"/><path class="sway" style="animation-delay:-1s" d="M135 121 q-3 -14 2 -28"/><path class="sway" style="animation-delay:-2s" d="M150 121 q3 -12 -1 -22"/><path class="sway" style="animation-delay:-.5s" d="M165 121 q-3 -15 2 -28"/><path class="sway" style="animation-delay:-1.5s" d="M180 122 q3 -13 -1 -24"/></g><path d="M232 100 c-2 -10 4 -14 1 -22 M232 100 c4 -6 9 -7 10 -16" stroke="#c2407e" stroke-width="4" fill="none" stroke-linecap="round"/><circle cx="262" cy="92" r="9" fill="#e9a35c"/><path d="M75 80 C120 95 160 112 240 88" stroke="#2f7d3c" stroke-width="2.5" fill="none" class="flow"/><path d="M240 105 C180 120 130 118 75 90" stroke="#f29b38" stroke-width="2.5" fill="none" class="flow rev"/></svg>';

/* A small fish drawn facing right (nose at x = 29, tail fin at the left), so it swims head first
   when the .swim animation moves it from left to right. */
function fish(y, color) {
  return '<svg viewBox="0 0 30 12" width="30" height="12" style="position:absolute;top:' + y + 'px;left:0" aria-hidden="true" focusable="false">' +
    '<path d="M29 6 C23 0 13 0 7 6 C13 12 23 12 29 6Z M7 6 L0 1 L0 11Z" fill="' + color + '"/>' +
    '<circle cx="24.5" cy="5" r="1" fill="#0b2a3c"/></svg>';
}

export function motionPv(level) {
  if (level === 'calm') return '<div style="position:absolute;inset:0;background:linear-gradient(#e7f4f5,#bfe0e3);overflow:hidden"><div style="position:absolute;left:14px;top:16px;right:14px;font:700 15px/1.35 var(--display);color:#0b2a3c">Movement only when you act: fades, hover lifts, a click-to-play story.</div><div style="position:absolute;left:14px;bottom:14px;display:flex;gap:6px"><span style="background:#0b2a3c;color:#fff;padding:5px 10px;border-radius:99px;font:700 10px var(--sans)">▶ Play the flow</span></div></div>';
  if (level === 'lively') return '<div style="position:absolute;inset:0;background:linear-gradient(#e7f4f5,#8fd3dc);overflow:hidden">' + miniScape + '</div>';
  return '<div style="position:absolute;inset:0;background:linear-gradient(#103a52,#0b2a3c);overflow:hidden">' +
    '<div class="swim" style="position:absolute;inset:0">' + fish(30, '#ffd166') + fish(50, '#f29b38') + '</div>' +
    '<div class="swim b" style="position:absolute;inset:0">' + fish(80, '#8fd3dc') + fish(100, '#ffd166') + '</div>' +
    '<div class="swim c" style="position:absolute;inset:0">' + fish(120, '#f28fb0') + '</div>' +
    '<div class="shimmer" style="position:absolute;inset:0;background:radial-gradient(circle at 30% 20%,rgba(143,211,220,.35),transparent 45%)"></div>' +
    '<div style="position:absolute;left:12px;bottom:10px;color:#fff;font:700 12px var(--sans)">Parallax, particles, scroll-driven scenes</div></div>';
}

/* A6: a tiny mock navigation bar showing each option's menu labels. */
const A6_ROUTES = ['Places', 'Voices', 'Open science', 'Learn'];
export function menuPv(menu, optionId) {
  const items = (menu || []).map((m, i) => {
    const last = optionId === 'compact' && i === menu.length - 1;
    return '<span class="a6-item' + (last ? ' a6-login' : '') + '">' + esc(m) + '</span>';
  }).join('');
  const routes = optionId === 'blend'
    ? '<div class="a6-routes">' + A6_ROUTES.map(r => '<span>' + esc(r) + '</span>').join('') + '</div>'
    : '';
  return '<div class="mk a6" style="background:#fff;color:#0b2a3c">' +
    '<div class="a6-bar"><img src="' + LOGO + '" class="logo" alt=""><b>SEASTRONG</b></div>' +
    '<div class="a6-menu">' + items + '</div>' + routes +
    '<div class="a6-page"><div class="bar l"></div><div class="bar m"></div><div class="row" style="margin-top:8px"><div class="tile" style="background:#e6f3f4"></div><div class="tile" style="background:#eef2e4"></div><div class="tile" style="background:#fde8ec"></div></div></div></div>';
}

/* ---------- demos ---------- */
export function demoToy(uid) {
  const hab = (k, icon, label, on) => '<button type="button" class="demo-chip" data-hab="' + k + '" aria-pressed="' + on + '"><span aria-hidden="true">' + icon + '</span> ' + label + '</button>';
  return '<div class="demo-box" data-demo="toy">' +
    '<p class="demo-title" id="' + uid + '-t">Try the “connect the seascape” idea (illustrative numbers)</p>' +
    '<div class="demo-chips" role="group" aria-labelledby="' + uid + '-t">' +
    hab('m', '🌳', 'Mangroves', true) + hab('s', '🌿', 'Seagrass', true) + hab('r', '🪸', 'Coral reef', true) + hab('w', '🌡️', '+1.5 °C heatwave', false) +
    '</div><div class="demo-bars" data-toybars aria-live="polite"></div>' +
    '<p class="demo-note">This is the kind of teaching tool the project’s ecosystem model could power later. For now it’s a design idea, not science.</p></div>';
}

export function demoMotion(uid) {
  return '<div class="demo-box" data-demo="motion">' +
    '<label class="demo-title" for="' + uid + '-r">Try it: how much movement feels right?</label>' +
    '<input class="demo-range" id="' + uid + '-r" type="range" min="0" max="2" step="1" value="1" aria-valuetext="Lively" data-motionrange>' +
    '<div class="demo-scale" aria-hidden="true"><span>Calm</span><span>Lively</span><span>Immersive</span></div>' +
    '<div class="demo-stage" data-motionstage aria-hidden="true"></div>' +
    '<p class="demo-note" data-motionlbl aria-live="polite"></p></div>';
}

export function demoDepth(uid) {
  const b = (v, label, on) => '<button type="button" data-depth="' + v + '" aria-pressed="' + on + '">' + label + '</button>';
  return '<div class="demo-box" data-demo="depth">' +
    '<div class="demo-row"><span class="demo-title" id="' + uid + '-t">Try it:</span>' +
    '<div class="demo-seg" role="group" aria-labelledby="' + uid + '-t ' + uid + '-g"><span class="sr-only" id="' + uid + '-g">reading depth</span>' +
    b(0, 'Glance', true) + b(1, 'Explain', false) + b(2, 'Deep dive', false) + '</div></div>' +
    '<div class="demo-depth" aria-live="polite">' +
    '<p data-depthtext="0"><b>Mangroves feed reefs.</b> Fish that grow up among mangrove roots later stock nearby reefs, so protecting one protects the other.</p>' +
    '<p data-depthtext="1" hidden><b>Mangroves feed reefs.</b> Many reef fish spend their juvenile months in mangroves and seagrass, where roots and blades hide them from predators. In the Caribbean, reefs near mangroves can hold far more of some fish species than reefs without them. SEASTRONG measures how strong these links are in Belize, Fiji and Seychelles, and whether they weaken as the water warms. <span class="demo-meta">1 figure · 3 min</span></p>' +
    '<p data-depthtext="2" hidden><b>Mangroves feed reefs.</b> We quantify mobile-link connectivity via underwater visual census, otolith-based growth models and stable-isotope mixing models across six or more cross-shelf corridors per region (WP4), then simulate it under warming in an agent-based model (WP7). <span class="demo-meta">Methods · Pre-registration · Dataset DOI · Code · Cite this</span></p>' +
    '</div><p class="demo-note">Same page, three depths. A reader moves deeper without being pushed to another page.</p></div>';
}

export const DEMOS = { demoToy, demoMotion, demoDepth };

PV.C2 = { calm: motionPv('calm'), lively: motionPv('lively'), immersive: motionPv('immersive') };

function toyUpdate(box) {
  const bars = box.querySelector('[data-toybars]');
  if (!bars) return;
  const on = k => box.querySelector('[data-hab="' + k + '"]').getAttribute('aria-pressed') === 'true';
  const m = on('m'), s = on('s'), r = on('r'), w = on('w');
  const fishN = r ? Math.round((30 + (m ? 30 : 0) + (s ? 20 : 0)) * (w ? 0.6 : 1)) : 5;
  const waves = Math.round(((r ? 45 : 0) + (s ? 20 : 0) + (m ? 30 : 0)) * (w ? 0.9 : 1));
  const carbon = Math.round(((m ? 52 : 0) + (s ? 36 : 0) + (r ? 4 : 0)) * (w ? 0.92 : 1));
  const bar = (lbl, v, c) => '<div class="demo-bar"><div class="demo-bar-head"><span>' + lbl + '</span><span>' + v + '</span></div>' +
    '<div class="demo-bar-track" aria-hidden="true"><div style="width:' + Math.min(v, 100) + '%;background:' + c + '"></div></div></div>';
  bars.innerHTML = bar('Reef fish', fishN, '#f29b38') + bar('Coastal protection', waves, '#0e7c86') + bar('Carbon stored', carbon, '#4c9a5b');
}

const MOTION_TEXT = {
  calm: 'Calm: nothing moves until you do.',
  lively: 'Lively: gentle, meaningful ambient motion (flows, swaying seagrass). This is the team proposal.',
  immersive: 'Immersive: continuous movement, parallax and particles.'
};
function motionUpdate(box, announce) {
  const r = box.querySelector('[data-motionrange]');
  if (!r) return;
  const lv = ['calm', 'lively', 'immersive'][+r.value] || 'lively';
  r.setAttribute('aria-valuetext', lv.charAt(0).toUpperCase() + lv.slice(1));
  box.querySelector('[data-motionstage]').innerHTML = motionPv(lv);
  const lbl = box.querySelector('[data-motionlbl]');
  if (announce || !lbl.textContent) lbl.textContent = MOTION_TEXT[lv];
}

/* Wire every demo inside root. Safe to call again after a re-render. */
export function wireDemos(root) {
  root.querySelectorAll('.demo-box').forEach(box => {
    if (box.dataset.wired) return;
    box.dataset.wired = '1';
    const kind = box.dataset.demo;
    if (kind === 'toy') {
      toyUpdate(box);
      box.addEventListener('click', e => {
        const t = e.target.closest('[data-hab]');
        if (!t) return;
        t.setAttribute('aria-pressed', String(t.getAttribute('aria-pressed') !== 'true'));
        toyUpdate(box);
      });
    } else if (kind === 'motion') {
      motionUpdate(box, false);
      box.addEventListener('input', e => { if (e.target.matches('[data-motionrange]')) motionUpdate(box, true); });
    } else if (kind === 'depth') {
      box.addEventListener('click', e => {
        const t = e.target.closest('[data-depth]');
        if (!t) return;
        box.querySelectorAll('[data-depth]').forEach(b => b.setAttribute('aria-pressed', String(b === t)));
        box.querySelectorAll('[data-depthtext]').forEach(d => { d.hidden = d.dataset.depthtext !== t.dataset.depth; });
      });
    }
  });
}

